import sys
MOD=998244353

def factor(x):
    d=2
    out={}
    while d*d<=x:
        while x%d==0:
            out[d]=out.get(d,0)+1
            x//=d
        d+=1
    if x>1:
        out[x]=out.get(x,0)+1
    return out

data=list(map(int,sys.stdin.buffer.read().split()))
n=data[0]
values=data[1:]
factors=[factor(x) for x in values]
primes=set()
for f in factors:
    primes.update(f)

answer=1
for p in primes:
    steps=[f.get(p,0) for f in factors]
    width=sum(steps)
    powers=[1]*(width+1)
    for h in range(1,width+1):
        powers[h]=powers[h-1]*p%MOD

    # d0: paths that have not visited height zero; d1: paths that have.
    d0=[0]*(width+1)
    d1=[0]*(width+1)
    for h in range(width+1):
        if h==0:
            d1[h]=1
        else:
            d0[h]=powers[h]

    for step in steps:
        nd0=[0]*(width+1)
        nd1=[0]*(width+1)
        for h in range(width+1):
            v0=d0[h]
            v1=d1[h]
            if not (v0 or v1):
                continue
            targets=(h,) if step==0 else (h+step,h-step)
            for nh in targets:
                if nh<0 or nh>width:
                    continue
                weight=powers[nh]
                if nh==0:
                    nd1[nh]=(nd1[nh]+(v0+v1)*weight)%MOD
                else:
                    if v0:
                        nd0[nh]=(nd0[nh]+v0*weight)%MOD
                    if v1:
                        nd1[nh]=(nd1[nh]+v1*weight)%MOD
        d0,d1=nd0,nd1
    answer=answer*sum(d1)%MOD

print(answer)

