import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    arr = data[1:]
    mx = max(arr)

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, mx + 1, p):
                if spf[v] == v:
                    spf[v] = p

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for v in range(p, mx + 1, p):
                phi[v] -= phi[v] // p

    acc = [0] * (mx + 1)
    divisor_cache = {1: [1]}
    ans = 0
    weight = 1
    out = []

    for x in arr:
        divs = divisor_cache.get(x)
        if divs is None:
            y = x
            factors = []
            while y > 1:
                p = spf[y]
                e = 0
                while y % p == 0:
                    y //= p
                    e += 1
                factors.append((p, e))
            divs = [1]
            for p, e in factors:
                old = divs[:]
                q = 1
                for _ in range(e):
                    q *= p
                    divs.extend(d * q for d in old)
            divisor_cache[x] = divs

        c = 0
        for d in divs:
            c += phi[d] * acc[d]
        c %= MOD
        for d in divs:
            z = acc[d] + weight
            if z >= MOD:
                z -= MOD
            acc[d] = z

        ans = (2 * ans + c) % MOD
        out.append(str(ans))
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(out))

