from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y))
            events[b].append((a,i))
        counts=[0]*(n+1)
        ids=[[] for _ in range(n+1)]
        heap=[]
        base=0
        gain=[0]*len(conflictingPairs)
        for r in range(1,n+1):
            for a,i in events[r]:
                if counts[a]==0: heapq.heappush(heap,-a)
                counts[a]+=1
                ids[a].append(i)
            while heap and counts[-heap[0]]==0: heapq.heappop(heap)
            top=-heap[0] if heap else 0
            base += r-top
            if top and counts[top]==1:
                heapq.heappop(heap)
                second=-heap[0] if heap else 0
                heapq.heappush(heap,-top)
                gain[ids[top][0]] += top-second
        return base+max(gain)

