import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = []
    pos = 2

    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        g = math.gcd(a, b)

        # Enumerate only the less efficient machine type. An optimal
        # solution never needs a full equal-production block of it.
        if p * b <= q * a:
            processes.append((a, p, b, q, 0, a // g))
        else:
            processes.append((a, p, b, q, 1, b // g))

    def feasible(target):
        total_cost = 0
        for a, p, b, q, mode, limit in processes:
            best = 10**30
            if mode == 0:  # S is more efficient; enumerate T machines
                for v in range(limit):
                    remaining = target - v * b
                    u = max(0, (remaining + a - 1) // a)
                    cost = v * q + u * p
                    if cost < best:
                        best = cost
            else:  # T is more efficient; enumerate S machines
                for u in range(limit):
                    remaining = target - u * a
                    v = max(0, (remaining + b - 1) // b)
                    cost = u * p + v * q
                    if cost < best:
                        best = cost

            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    main()

