class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # steps[x] = number of popcount operations needed to reach 1.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # Binomial coefficients, modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for a in range(n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        used = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                # Make this bit 0, then choose the remaining set bits freely.
                for total_ones in range(1, n + 1):
                    if steps[total_ones] < k:
                        need = total_ones - used
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                used += 1

        return ans % MOD

