    if N % d != 0:
        continue
    a = N // d
    # N/d = 3*y^2 + 3*d*y + d^2
    disc = 12 * a - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        print(y + d, y)
