            nr, nc = r + dr[d], c + dc[d]
            best = dp(nr, nc, d, nxt, can_turn)
            if can_turn:
                nd = (d + 1) % 4
                nr, nc = r + dr[nd], c + dc[nd]
                best = max(best, dp(nr, nc, nd, nxt, False))
