from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        unused = set(range(1, n + 1))
        ans = []
        prev = None

        while unused:
            chosen = None
            for x in sorted(unused):
                if prev is not None and (x & 1) == (prev & 1):
                    continue

                remaining_odds = odds - (x & 1)
                remaining_evens = evens - (1 - (x & 1))
                remaining_length = len(unused) - 1

                if remaining_length == 0:
                    ways = 1
                else:
                    next_is_odd = 1 - (x & 1)
                    needed_odds = ((remaining_length + 1) // 2
                                   if next_is_odd else remaining_length // 2)
                    needed_evens = remaining_length - needed_odds
                    if (remaining_odds == needed_odds and
                            remaining_evens == needed_evens):
                        ways = math.factorial(remaining_odds) * math.factorial(remaining_evens)
                    else:
                        ways = 0

                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            ans.append(chosen)
            unused.remove(chosen)
            if chosen & 1:
                odds -= 1
            else:
                evens -= 1
            prev = chosen

        return ans

