class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for i in range(m):
            j = n - 1 - i
            weight = pow(10, i, k)
            if j != i:
                weight += pow(10, j, k)
            weights.append(weight % k)

        # Each mask records the residues attainable using the indicated suffix
        # of mirrored digit positions.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Only residue 0 is attainable with no positions left.
        for i in range(m - 1, -1, -1):
            next_mask = suffix[i + 1]
            mask = 0
            for residue in range(k):
                if (next_mask >> residue) & 1:
                    for digit in range(10):
                        new_residue = (residue + digit * weights[i]) % k
                        mask |= 1 << new_residue
            suffix[i] = mask

        chosen = []
        remainder = 0
        for i, weight in enumerate(weights):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                needed = (-remainder - digit * weight) % k
                if (suffix[i + 1] >> needed) & 1:
                    chosen.append(str(digit))
                    remainder = (remainder + digit * weight) % k
                    break

        half = ''.join(chosen)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

