            weights.append((pow(10, i, k) + (pow(10, j, k) if j != i else 0)) % k)
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            w = weights[i]
            old = suffix[i + 1]
            mask = 0
            for r in range(k):
                if old >> r & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * w) % k)
            suffix[i] = mask
        digits = []
        rem = 0
        for i, w in enumerate(weights):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - d * w) % k
                if suffix[i + 1] >> need & 1:
                    digits.append(str(d))
                    rem = (rem + d * w) % k
                    break
        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

