from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        log = n.bit_length()
        up = [nxt]
        for _ in range(1, log):
            prev = up[-1]
            up.append([prev[prev[i]] if prev[i] < n else n for i in range(n)])

        prefix = [0]
        for value in nums:
            prefix.append(prefix[-1] + value)

        def cost(left: int, right: int) -> int:
            pos = left
            maximum_sum = 0
            for level in range(log - 1, -1, -1):
                if pos == n:
                    break
                dest = up[level][pos]
                if dest <= right + 1:
                    maximum_sum += (dest - pos) * nums[pos]
                    pos = dest
            if pos <= right:
                maximum_sum += (right - pos + 1) * nums[pos]
            return maximum_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for left in range(n):
            lo, hi = left, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(left, mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - left + 1
        return answer

