import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, len(data), 2)]

    # For two functions i and j, putting i outside j is at least as
    # good exactly when (A_i - 1) / B_i >= (A_j - 1) / B_j.
    def compare(x, y):
        a, b = x
        c, d = y
        left = (a - 1) * d
        right = (c - 1) * b
        return (left > right) - (left < right)

    # Process in ascending order: chosen functions are applied from inner
    # to outer, so their outer-to-inner order is descending by this ratio.
    funcs.sort(key=cmp_to_key(compare))
    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for count in range(k, 0, -1):
            if dp[count - 1] is not None:
                value = a * dp[count - 1] + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value
    print(dp[k])

if __name__ == '__main__':
    main()

