from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(part):
            if not part:
                return list(range(n + 1))
            result = []
            pos = s.find(part)
            while pos != -1:
                result.append(pos)
                pos = s.find(part, pos + 1)
            return result

        starts_a, starts_b, starts_c = map(occurrences, (a, b, c))
        best = n + 1

        for start in starts_a:
            next_b = bisect_left(starts_b, start + len(a))
            if next_b == len(starts_b):
                continue
            start_b = starts_b[next_b]

            next_c = bisect_left(starts_c, start_b + len(b))
            if next_c == len(starts_c):
                continue
            end = starts_c[next_c] + len(c)
            best = min(best, end - start)

        return -1 if best == n + 1 else best

