def solve():
    data = sys.stdin.buffer.read().split()
    K = int(data[0])
    s, t = data[1], data[2]
    n, m = len(s), len(t)

    if abs(n - m) > K:
        print("No")
        return

    def snake(x, k):
        y = x - k
        while x < n and 0 <= y < m and s[x] == t[y]:
            x += 1
            y += 1
        return x

    # v[k] is the furthest position in S reachable on diagonal k=i-j
    # using the current number of edits, followed by matching characters.
    v = {0: snake(0, 0)}
    if v[0] == n and v[0] == m:
        print("Yes")
        return

    for edits in range(1, K + 1):
        nv = {}
        for k in range(-edits, edits + 1):
            candidates = []

            # Delete a character from S: (i,j) -> (i+1,j).
            if k - 1 in v:
                x = v[k - 1] + 1
                y = x - k
                if 0 <= x <= n and 0 <= y <= m:
                    candidates.append(x)

            # Insert a character into S: (i,j) -> (i,j+1).
            if k + 1 in v:
                x = v[k + 1]
                y = x - k
                if 0 <= x <= n and 0 <= y <= m:
                    candidates.append(x)

            # Replace one character: (i,j) -> (i+1,j+1).
            if k in v:
                x = v[k] + 1
                y = x - k
                if 0 <= x <= n and 0 <= y <= m:
                    candidates.append(x)

            if not candidates:
                continue

            x = snake(max(candidates), k)
            nv[k] = x
            if x == n and x - k == m:
                print("Yes")
                return

        v = nv

    print("No")

