from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, preserving ascending child order.
        postorder = []
        stack = [(0, False)]
        while stack:
            node, exiting = stack.pop()
            if exiting:
                postorder.append(node)
            else:
                stack.append((node, True))
                for child in reversed(children[node]):
                    stack.append((child, False))

        position = [0] * n
        subtree_size = [1] * n
        chars = []
        for i, node in enumerate(postorder):
            position[node] = i
            chars.append(s[node])
            for child in children[node]:
                subtree_size[node] += subtree_size[child]
        text = ''.join(chars)

        # Manacher's algorithm: odd[i] and even[i] are palindrome radii.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for node in range(n):
            end = position[node]
            length = subtree_size[node]
            start = end - length + 1
            if length % 2:
                center = (start + end) // 2
                answer[node] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[node] = even[center] >= length // 2
        return answer

