class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        answer = None

        for outlier in nums:
            remainder = total - outlier
            if remainder % 2 != 0:
                continue

            sum_value = remainder // 2
            needed = 2 if sum_value == outlier else 1
            if counts[sum_value] >= needed:
                if answer is None or outlier > answer:
                    answer = outlier

        return answer

