import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        hi = 10 ** length - 1

        # Prime sieve over all numbers that can occur while retaining the
        # original number of digits.
        prime = bytearray(b'\x01') * (hi + 1)
        prime[0] = prime[1] = 0
        for p in range(2, int(hi ** 0.5) + 1):
            if prime[p]:
                start = p * p
                prime[start:hi + 1:p] = b'\x00' * (((hi - start) // p) + 1)

        # The initial value and destination must also be non-prime.
        if prime[n] or prime[m]:
            return -1

        powers = [10 ** i for i in range(length)]
        dist = {n: n}  # The cost includes every value, including the start.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for pos, power in enumerate(powers):
                digit = (value // power) % 10
                for change in (-1, 1):
                    next_digit = digit + change
                    if not 0 <= next_digit <= 9:
                        continue
                    # A leading zero would no longer be a digit of this
                    # same-length integer.
                    if pos == length - 1 and next_digit == 0:
                        continue
                    nxt = value + change * power
                    if prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist.get(nxt, float('inf')):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

