from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the LCP of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        ans = 0
        # Reuse this array to compute LCP(nums[i:], nums[j:]) as i decreases.
        lcp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            # nums[:i] is a prefix of nums[i:j] when this holds and j >= 2*i.
            first_condition = 2 * i <= n and z[i] >= i
            for j in range(i + 1, n):
                lcp[j] = lcp[j + 1] + 1 if nums[i] == nums[j] else 0
                # nums[i:j] is a prefix of nums[j:] iff its length does not
                # exceed their longest common prefix.
                if lcp[j] >= j - i or (first_condition and j >= 2 * i):
                    ans += 1
        return ans

