from typing import List
class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        marked = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            ndp = [neg] * (m + 1)
            gain = 1 if i in marked else 0
            for j in range(m + 1):
                if dp[j] == neg:
                    continue
                ndp[j] = max(ndp[j], dp[j] + gain)
                if j < m and ch == pattern[j]:
                    ndp[j + 1] = max(ndp[j + 1], dp[j])
            dp = ndp
        return dp[m]

