class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(p) for p in points}
        best = -1
        n = len(points)

        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]
                if x1 == x2 or y1 == y2:
                    continue

                left, right = sorted((x1, x2))
                bottom, top = sorted((y1, y2))
                corners = {
                    (left, bottom), (left, top),
                    (right, bottom), (right, top),
                }
                if not corners.issubset(point_set):
                    continue

                # Any additional point in the closed rectangle invalidates it.
                if any(
                    (x, y) not in corners
                    and left <= x <= right
                    and bottom <= y <= top
                    for x, y in points
                ):
                    continue

                best = max(best, (right - left) * (top - bottom))

        return best

